message.content:
{
  "sections": [
    {
      "title": "Why you were in the hospital",
      "bullets": [
        {
          "id": "b1",
          "text": "Your heart was not pumping strongly enough and you had trouble breathing and swollen legs.",
          "sources": ["p1:L6", "term:CHF", "term:SOB"]
        },
        {
          "id": "b2",
          "text": "You also have narrowed heart arteries and high blood pressure.",
          "sources": ["p1:L7", "term:CAD", "term:HTN"]
        }
      ]
    },
    {
      "title": "Your medicines",
      "bullets": [
        {
          "id": "b3",
          "text": "Furosemide 40 mg, take two times a day by mouth. This is a water pill that helps your body get rid of extra fluid.",
          "sources": ["p1:L11", "drug:furosemide", "term:BID", "term:PO"]
        },
        {
          "id": "b4",
          "text": "Lisinopril 20 mg, take one time a day by mouth. This medicine lowers blood pressure and helps the heart. (Changed from 40 mg.)",
          "sources": ["p1:L12", "drug:lisinopril", "term:PO"]
        },
        {
          "id": "b5",
          "text": "Carvedilol 12.5 mg, take two times a day by mouth with food. This medicine helps the heart work better and lowers blood pressure.",
          "sources": ["p1:L13", "drug:carvedilol", "term:BID", "term:PO"]
        },
        {
          "id": "b6",
          "text": "Check the carvedilol dose with your care team before taking it. The hospital record says 25 mg, but your discharge paper says 12.5 mg.",
          "sources": ["conflict:conflict-2", "p1:L13", "record:32"]
        },
        {
          "id": "b7",
          "text": "Clopidogrel 75 mg, take one time a day by mouth. This is a blood thinner that helps prevent heart attacks and strokes.",
          "sources": ["p1:L14", "drug:clopidogrel", "term:PO"]
        },
        {
          "id": "b8",
          "text": "Rosuvastatin 40 mg, take every night at bedtime by mouth. This medicine lowers cholesterol.",
          "sources": ["p1:L15", "drug:rosuvastatin", "term:QHS", "term:PO"]
        },
        {
          "id": "b9",
          "text": "Nitroglycerin 0.4 mg, let it melt under your tongue every 5 minutes as needed for chest pain, up to 3 doses. This medicine prevents chest pain from heart disease.",
          "sources": ["p1:L16", "drug:nitroglycerin", "term:SL", "term:PRN"]
        },
        {
          "id": "b10",
          "text": "Stop taking naproxen. NSAIDs worsen heart failure.",
          "sources": ["p1:L17", "drug:naproxen"]
        },
        {
          "id": "b11",
          "text": "Ask your doctor if you should keep taking simvastatin 20 mg. It is in your hospital record but not on your discharge paper.",
          "sources": ["record:3"]
        },
        {
          "id": "b12",
          "text": "Ask your doctor if you should keep taking metoprolol succinate 100 mg. It is in your hospital record but not on your discharge paper.",
          "sources": ["record:4"]
        },
        {
          "id": "b13",
          "text": "Ask your doctor if you should keep taking prasugrel 10 mg. It is in your hospital record but not on your discharge paper.",
          "sources": ["record:35"]
        },
        {
          "id": "b14",
          "text": "Ask your doctor if you should keep taking alendronic acid 10 mg. It is in your hospital record but not on your discharge paper.",
          "sources": ["record:36"]
        }
      ]
    },
    {
      "title": "What to do at home",
      "bullets": [
        {
          "id": "b15",
          "text": "Eat a low sodium diet, 2 grams of salt per day.",
          "sources": ["p1:L19"]
        },
        {
          "id": "b16",
          "text": "Limit fluids to 1.5 liters per day.",
          "sources": ["p1:L19"]
        },
        {
          "id": "b17",
          "text": "Weigh yourself every morning before breakfast and write it down.",
          "sources": ["p1:L20"]
        },
        {
          "id": "b18",
          "text": "Do not lift more than 10 pounds for 1 week.",
          "sources": ["p1:L21"]
        }
      ]
    },
    {
      "title": "Your follow-up visits",
      "bullets": [
        {
          "id": "b19",
          "text": "Cardiology clinic with Dr. Okafor in 1 week.",
          "sources": ["p1:L23"]
        },
        {
          "id": "b20",
          "text": "Blood test for salts and kidneys in 3 days.",
          "sources": ["p1:L24", "term:BMP"]
        },
        {
          "id": "b21",
          "text": "See your family doctor in 2 weeks.",
          "sources": ["p1:L25", "term:PCP"]
        }
      ]
    }
  ],
  "med_schedule": [
