      "sources": ["p1:L16"]
    }
  ],
  "call_911_if": [
    {
      "id": "w1",
      "text": "Weight gain of more than 2 pounds in a day or 5 pounds in a week.",
      "sources": ["p1:L26", "p1:L27"]
    },
    {
      "id": "w2",
      "text": "Trouble breathing at rest or when lying flat.",
      "sources": ["p1:L26", "p1:L28"]
    },
    {
      "id": "w3",
      "text": "Chest pain not relieved by 3 nitroglycerin doses.",
      "sources": ["p1:L26", "p1:L29"]
    },
    {
      "id": "w4",
      "text": "Fainting or a very slow heartbeat.",
      "sources": ["p1:L26", "p1:L30"]
    }
  ],
  "questions_for_your_doctor": [
    "Should I keep taking simvastatin 20 mg?",
    "Should I keep taking metoprolol succinate 100 mg?",
    "Should I keep taking prasugrel 10 mg?",
    "Should I keep taking alendronic acid 10 mg?"
  ]
}
